def dedupe_current_years(apps, schema_editor):
    """The database now allows one current year per school. If a school somehow has several, keep the one that starts
    latest and clear the flag on the others (nothing is deleted or archived); the count is printed for the operator."""
    AcademicYear = apps.get_model("academics", "AcademicYear")
    fixed = 0
    school_ids = AcademicYear.objects.filter(is_current=True).values_list("school_id", flat=True).distinct()
    for school_id in school_ids:
        years = list(AcademicYear.objects.filter(school_id=school_id, is_current=True).order_by("-start_date", "-created_at"))
        for extra in years[1:]:
            extra.is_current = False
            extra.save(update_fields=["is_current"])
            fixed += 1
    if fixed:
        print(f"\n  [academic years] cleared the 'current' flag on {fixed} extra year(s) so each school has at most one.")


def backfill_enrollments(apps, schema_editor):
    """Builds the enrolment history from evidence that already exists: each student's current class/year, and the
    old/new class and year on every promotion record. Never overwrites an existing enrolment, never guesses: a row is
    created only where a student, a year and a class are all recorded. Prints a reconciliation summary."""
    Student = apps.get_model("students", "Student")
    PromotionRecord = apps.get_model("academics", "PromotionRecord")
    StudentEnrollment = apps.get_model("academics", "StudentEnrollment")
    Section = apps.get_model("academics", "Section")

    created = {"current": 0, "promotion": 0}
    conflicts = 0

    def ensure(student_id, school_id, year_id, class_id, section_id, source, outcome=""):
        nonlocal conflicts
        row, was_created = StudentEnrollment.objects.get_or_create(
            student_id=student_id,
            academic_year_id=year_id,
            defaults={"school_id": school_id, "school_class_id": class_id, "section_id": section_id, "source": source, "outcome": outcome},
        )
        if not was_created:
            if row.school_class_id != class_id:
                conflicts += 1  # two sources disagree: keep the first, the report below flags it for review
            elif outcome and not row.outcome:
                row.outcome = outcome
                row.save(update_fields=["outcome"])
        return was_created

    for student in Student.objects.filter(current_academic_year__isnull=False, current_class__isnull=False).iterator():
        section_id = None
        if student.current_section_id:
            section = Section.objects.filter(pk=student.current_section_id).first()
            if section and section.academic_year_id == student.current_academic_year_id and section.school_class_id == student.current_class_id:
                section_id = section.pk
        if ensure(student.pk, student.school_id, student.current_academic_year_id, student.current_class_id, section_id, "backfill_current"):
            created["current"] += 1

    for record in PromotionRecord.objects.order_by("created_at").iterator():
        outcome = {"promoted": "promoted", "repeated": "repeated"}.get(record.status, "")
        if ensure(record.student_id, record.school_id, record.previous_academic_year_id, record.previous_class_id, None, "backfill_promotion", outcome):
            created["promotion"] += 1
        if record.new_class_id and record.new_academic_year_id:
            if ensure(record.student_id, record.school_id, record.new_academic_year_id, record.new_class_id, None, "backfill_promotion"):
                created["promotion"] += 1

    total = StudentEnrollment.objects.count()
    without = Student.objects.exclude(enrollments__isnull=False).exclude(status__in=["applicant", "archived"]).count()
    print(
        f"\n  [enrolments] created {created['current']} from current classes and {created['promotion']} from promotion records "
        f"({total} total); {conflicts} conflicting record(s) kept as first seen; {without} non-applicant student(s) have no enrolment "
        "(no recorded class/year - review them before the first rollover)."
    )



